import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void fused_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    float* __restrict__ out,
    const int batch_size,
    const int input_size,
    const int hidden_size,
    const float scaling_factor
){
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < batch_size) {
        float sumVal = 0.0f;
        for (int j = 0; j < hidden_size; j++) {
            float dotVal = 0.0f;
            for (int k = 0; k < input_size; k++) {
                dotVal += x[i * input_size + k] * w[j * input_size + k];
            }
            dotVal /= 2.0f;
            sumVal += dotVal;
        }
        out[i] = sumVal * scaling_factor;
    }
}

torch::Tensor fused_forward_cuda(
    torch::Tensor x, 
    torch::Tensor w,
    float scaling_factor
){
    const auto batch_size = x.size(0);
    const auto input_size = x.size(1);
    const auto hidden_size = w.size(0);

    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(x.device());
    auto out = torch::zeros({(long)batch_size, 1}, options);

    const int blockSize = 256;
    const int gridSize = (batch_size + blockSize - 1) / blockSize;

    fused_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(), 
        w.data_ptr<float>(), 
        out.data_ptr<float>(),
        batch_size, 
        input_size, 
        hidden_size, 
        scaling_factor
    );

    return out;
}
"""

fused_cpp_source = r"""
torch::Tensor fused_forward_cuda(
    torch::Tensor x, 
    torch::Tensor w,
    float scaling_factor
);
"""

fused_module = load_inline(
    name="fused_module",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=["fused_forward_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that fuses matrix multiplication, division, summation, and scaling
    into a single custom CUDA kernel for improved performance.
    """
    def __init__(self, input_size, hidden_size, scaling_factor):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.randn(hidden_size, input_size))
        self.scaling_factor = scaling_factor
        self.fused_module = fused_module

    def forward(self, x):
        return self.fused_module.fused_forward_cuda(x, self.weight, self.scaling_factor)
